display: flex;
  gap: 14px;
  transition: transform 0.5s ease;
  will-change: transform;
  align-items: stretch;
  height: 100%;
  width: 100%;
  justify-content: flex-start !important;
  margin-right: auto !important;

flex: 0 0 calc((100% - 56px) / 5);
  width: calc((100% - 56px) / 5);
  min-width: calc((100% - 56px) / 5);
  height: 100%;
  border-radius: 22px;
  overflow: hidden;
  background: rgba(255,255,255,0.05);
  border: 6px solid #000;
  pointer-events: none;

width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background: rgba(255,255,255,0.06);

display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;

min-height: calc(100vh - 100px);
  padding: 28px 16px 80px;
  background: #000;

position: relative;
  display: block;
  height: 180px;
  border-radius: 28px;
  overflow: hidden;
  border: 2px solid rgba(255,255,255,0.22);
  color: #fff;
  text-decoration: none;
  background: #111;

position: absolute;
  left: 18px;
  bottom: 18px;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(0,0,0,0.78);
  border: 1px solid rgba(255,255,255,0.22);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;

position: absolute !important;

  /* .collection-box has 24px top padding, so -24px moves the label
     anchor from the inner content area up to the actual plate top edge. */
  top: -24px !important;
  left: 50% !important;
  right: auto !important;
  bottom: auto !important;

  transform: translate(-50%, -50%) !important;

  z-index: 50 !important;
  margin: 0 !important;

  width: max-content !important;
  max-width: calc(100% - 48px) !important;

  text-align: center !important;
  white-space: nowrap !important;
  pointer-events: none !important;

body.home,
  body.front-page,
  body.page-template-front-page {
    --dkg-home-stage-width: 1400px;
    --dkg-home-stage-scale: min(1, calc((100vw - 48px) / 1400));
    --dkg-browser-zoom-counter: 1;
    overflow-x: hidden !important;
  }

  /*
    HEADER FULL-BLEED FIX:
    The header itself should stretch edge-to-edge.
    Do NOT scale the header background/container.
  */
  body.home .site-header,
  body.front-page .site-header,
  body.page-template-front-page .site-header {
    width: 100vw !important;
    max-width: none !important;
    min-width: 100vw !important;

    margin-left: calc(50% - 50vw) !important;
    margin-right: 0 !important;

    transform: none !important;
    transform-origin: top center !important;

    box-sizing: border-box !important;
  }

  /*
    Header content gets counter-scaled, not the full-width header background.
    These selectors cover your current header structure and common wrappers.
  */
  body.home .site-header > *,
  body.front-page .site-header > *,
  body.page-template-front-page .site-header > * {
    transform: scale(var(--dkg-browser-zoom-counter)) !important;
    transform-origin: top center !important;
  }

  /*
    If the header has nav/logo elements without a wrapper, keep their layout
    from stretching strangely.
  */
  body.home .site-header .site-logo,
  body.home .site-header .nav,
  body.home .site-header .nav a,
  body.home .site-header .nav-social,
  body.front-page .site-header .site-logo,
  body.front-page .site-header .nav,
  body.front-page .site-header .nav a,
  body.front-page .site-header .nav-social,
  body.page-template-front-page .site-header .site-logo,
  body.page-template-front-page .site-header .nav,
  body.page-template-front-page .site-header .nav a,
  body.page-template-front-page .site-header .nav-social {
    box-sizing: border-box !important;
  }

  /*
    COLLECTION STAGE:
    This is the fixed plate area. It scales down only if viewport width
    physically cannot fit it, and also counter-scales against browser zoom.
  */
  body.home .collections-section,
  body.front-page .collections-section,
  body.page-template-front-page .collections-section {
    width: var(--dkg-home-stage-width) !important;
    max-width: none !important;
    min-width: var(--dkg-home-stage-width) !important;

    margin-left: auto !important;
    margin-right: auto !important;

    padding-left: 0 !important;
    padding-right: 0 !important;

    transform: scale(calc(var(--dkg-home-stage-scale) * var(--dkg-browser-zoom-counter))) !important;
    transform-origin: top center !important;

    box-sizing: border-box !important;
  }

  body.home .collections-stack,
  body.front-page .collections-stack,
  body.page-template-front-page .collections-stack {
    width: var(--dkg-home-stage-width) !important;
    max-width: none !important;
    min-width: var(--dkg-home-stage-width) !important;

    align-items: center !important;
    gap: 36px !important;

    box-sizing: border-box !important;
  }

  body.home .collection-link,
  body.front-page .collection-link,
  body.page-template-front-page .collection-link {
    width: var(--dkg-home-stage-width) !important;
    max-width: none !important;
    min-width: var(--dkg-home-stage-width) !important;

    margin-left: auto !important;
    margin-right: auto !important;

    overflow: visible !important;
    box-sizing: border-box !important;
  }

  body.home .collection-box,
  body.front-page .collection-box,
  body.page-template-front-page .collection-box {
    width: var(--dkg-home-stage-width) !important;
    max-width: none !important;
    min-width: var(--dkg-home-stage-width) !important;

    height: 260px !important;
    min-height: 260px !important;
    max-height: 260px !important;

    padding: 24px 24px 4px !important;

    overflow: visible !important;
    position: relative !important;
    box-sizing: border-box !important;
  }

  body.home .collection-bg,
  body.front-page .collection-bg,
  body.page-template-front-page .collection-bg {
    overflow: hidden !important;
  }

  body.home .product-track,
  body.front-page .product-track,
  body.page-template-front-page .product-track {
    width: 100% !important;
    height: 100% !important;
    gap: 14px !important;
    justify-content: flex-start !important;
  }

  body.home .product-card,
  body.front-page .product-card,
  body.page-template-front-page .product-card {
    flex: 0 0 calc((100% - 56px) / 5) !important;
    width: calc((100% - 56px) / 5) !important;
    min-width: calc((100% - 56px) / 5) !important;
    height: 100% !important;
  }

width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: center center !important;
  display: block !important;
  image-rendering: auto !important;

html,
  body {
    overflow-x: hidden !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop).home,
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop).front-page,
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop).page-template-front-page {
    width: 100% !important;
    max-width: 100% !important;
    overflow-x: hidden !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collections-stack {
    width: calc(100vw - 16px) !important;
    max-width: calc(100vw - 16px) !important;

    margin-left: 0 !important;
    margin-right: 0 !important;

    position: relative !important;
    left: 50% !important;
    right: auto !important;
    transform: translateX(-50%) !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;

    gap: clamp(22px, 5.5vw, 34px) !important;
    padding-left: 0 !important;
    padding-right: 0 !important;

    box-sizing: border-box !important;
    overflow: visible !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-link {
    width: 100% !important;
    max-width: 100% !important;
    display: block !important;
    overflow: visible !important;
    box-sizing: border-box !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-box {
    width: 100% !important;
    max-width: 100% !important;

    min-height: clamp(134px, 38vw, 184px) !important;
    height: clamp(134px, 38vw, 184px) !important;

    position: relative !important;
    overflow: hidden !important;
    box-sizing: border-box !important;

    transform: none !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  /*
    Keep the real plate background stable.
    Do not turn this into a carousel track.
  */
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-bg {
    width: 100% !important;
    height: 100% !important;
    min-height: inherit !important;

    overflow: hidden !important;
    border-radius: clamp(16px, 5vw, 28px) !important;
    box-sizing: border-box !important;
    position: relative !important;

    background-repeat: no-repeat !important;
    background-size: cover !important;
    background-position: center center !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-box.dkg-mobile-main-plate-prepared {
    --dkg-mobile-gap-px: 8px;
    --dkg-mobile-slot-px: 100px;
    --dkg-mobile-step-px: 108px;
    --dkg-mobile-viewport-pad-x: 14px;
    --dkg-mobile-viewport-pad-y: 26px;
  }

  /*
    Hide original product/product-track layer on mobile.
    The cloned mobile carousel is the only visible product layer.

    Important:
    - Do not hide .collection-bg itself.
    - Do not hide .collection-label.
    - Do not hide .dkg-mobile-carousel-viewport.
  */
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-box.dkg-mobile-main-plate-prepared .dkg-mobile-original-product-source,
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .collection-box.dkg-mobile-main-plate-prepared .dkg-mobile-original-track-source {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
  }

  /*
    Separate cloned carousel layer.
  */
  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .dkg-mobile-carousel-viewport {
    position: absolute !important;
    inset: var(--dkg-mobile-viewport-pad-y) var(--dkg-mobile-viewport-pad-x) var(--dkg-mobile-viewport-pad-y) var(--dkg-mobile-viewport-pad-x) !important;

    overflow: hidden !important;
    box-sizing: border-box !important;

    display: block !important;
    z-index: 4 !important;
    pointer-events: auto !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .dkg-mobile-carousel-viewport .dkg-mobile-product-track {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: stretch !important;

    gap: var(--dkg-mobile-gap-px) !important;

    width: max-content !important;
    max-width: none !important;
    height: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    position: relative !important;
    left: 0 !important;
    right: auto !important;

    box-sizing: border-box !important;

    overflow: visible !important;
    transform: translate3d(0, 0, 0) !important;
    will-change: transform !important;

    touch-action: pan-y !important;
    scrollbar-width: none !important;
  }

  body:not(.page-mobile-shop):not(.page-template-page-mobile-shop) .dkg-mobile-carousel-viewport .dkg-mobile-product-track.dkg-mobile-track-animate {
