117:   function setupRotator(rotator) {
118:     if (!rotator || rotator.dataset.dkgCrossfadeReady === "1") return;
119:     rotator.dataset.dkgCrossfadeReady = "1";
120: 
121:     const frame = rotator.querySelector(FRAME_SELECTOR) || rotator;
122:     const originalImg = frame.querySelector(IMG_SELECTOR);
