133:     images.forEach(preload);
134: 
135:     /*
136:       Stop the old visual fade class from making the only image disappear.
137:       We are now taking over the visible animation.
138:     */
139:     originalImg.classList.remove("is-fading");
140:     originalImg.classList.add("dkg-header-picture-img-layer", "is-active");
141: 
142:     const layerA = originalImg;
143:     const layerB = originalImg.cloneNode(true);
144: 
145:     layerB.classList.remove("is-active", "is-fading");
146:     layerB.classList.add("dkg-header-picture-img-layer");
147:     layerB.setAttribute("aria-hidden", "true");
