151:     let activeLayer = layerA;
152:     let hiddenLayer = layerB;
153: 
154:     let currentIndex = Math.max(0, images.indexOf(layerA.currentSrc || layerA.src));
155:     if (!images[currentIndex]) {
156:       currentIndex = 0;
157:       layerA.src = images[0];
158:     }
159: 
160:     /*
161:       Try to silence old single-image source swaps.
162:       If the old script changes the first image's src, we snap it back to the active image.
163:     */
164:     const observer = new MutationObserver(() => {
165:       if (activeLayer === layerA && layerA.src !== images[currentIndex]) {
166:         layerA.src = images[currentIndex];
167:       }
168:       layerA.classList.remove("is-fading");
169:       layerB.classList.remove("is-fading");
170:     });
171: 
172:     observer.observe(layerA, {
173:       attributes: true,
174:       attributeFilter: ["src", "class"]
175:     });
176: 
177:     function crossfadeTo(nextIndex) {
178:       const nextUrl = images[nextIndex];
179:       if (!nextUrl) return;
