184:       // Force browser to register opacity 0 before fading in.
185:       hiddenLayer.offsetHeight;
186: 
187:       hiddenLayer.classList.add("is-active");
188:       activeLayer.classList.remove("is-active");
189: 
190:       const oldActive = activeLayer;
191:       activeLayer = hiddenLayer;
192:       hiddenLayer = oldActive;
193:       currentIndex = nextIndex;
194: 
195:       window.setTimeout(() => {
196:         hiddenLayer.classList.remove("is-active", "is-fading");
197:       }, FADE_MS + 80);
198:     }
199: 
200:     if (images.length > 1) {
201:       window.setInterval(() => {
202:         const nextIndex = (currentIndex + 1) % images.length;
203:         crossfadeTo(nextIndex);
204:       }, DISPLAY_MS);
