  1: function setupAutoLoop(shell, shellIndex) {
  2:       const track = shell.querySelector('.product-track');
  3:       if (!track) return;
  4: 
  5:       const originalCards = Array.from(track.children);
  6:       const originalCount = originalCards.length;
  7: 
  8:       if (originalCount <= 5) {
  9:         return;
 10:       }
 11: 
 12:       originalCards.forEach(card => {
 13:         const clone = card.cloneNode(true);
 14:         clone.setAttribute('aria-hidden', 'true');
 15:         track.appendChild(clone);
 16:       });
 17: 
 18:       let stepWidth = 0;
 19:       const transitionMs = 500;
 20: 
 21:       const delayOptions = [1400, 1750, 2100, 1600, 1950, 2300];
 22:       const startOffsetOptions = [0, 2, 1, 3, 4, 2];
 23: 
 24:       const autoDelay = delayOptions[shellIndex % delayOptions.length];
 25:       let index = startOffsetOptions[shellIndex % startOffsetOptions.length] % originalCount;
 26: 
 27:       function measureStepWidth() {
 28:         const firstCard = track.querySelector('.product-card');
 29:         if (!firstCard) return 0;
 30:         const cardWidth = firstCard.getBoundingClientRect().width;
 31:         const styles = window.getComputedStyle(track);
 32:         const gap = parseFloat(styles.gap || styles.columnGap || 0);
 33:         return cardWidth + gap;
 34:       }
 35: 
 36:       function render(animated = true) {
 37:         stepWidth = measureStepWidth();
 38:         track.style.transition = animated ? `transform ${transitionMs}ms ease` : 'none';
 39:         track.style.transform = `translateX(-${index * stepWidth}px)`;
 40:       }
 41: 
 42:       function nextStep() {
 43:         index += 1;
 44:         render(true);
 45: 
 46:         if (index >= originalCount) {
 47:           setTimeout(() => {
 48:             index = 0;
 49:             render(false);
 50:           }, transitionMs + 30);
 51:         }
 52:       }
 53: 
 54:       window.addEventListener('resize', () => {
 55:         render(false);
 56:       });
 57: 
 58:       render(false);
 59: 
 60:       const initialDelay = 250 + (shellIndex * 180);
 61:       setTimeout(() => {
 62:         setInterval(nextStep, autoDelay);
 63:       }, initialDelay);
 64:     }
 65: 
 66:     document.querySelectorAll('.auto-loop').forEach((shell, index) => {
 67:       setupAutoLoop(shell, index);
 68:     });
