269: function dkg_redirect_mobile_shop_visitors() {
270:     if (is_admin()) {
271:         return;
272:     }
273: 
274:     if (wp_doing_ajax()) {
275:         return;
276:     }
277: 
278:     if (!function_exists('wp_is_mobile') || !wp_is_mobile()) {
279:         return;
280:     }
281: 
282:     /*
283:      * Do not redirect WooCommerce account/cart/checkout pages.
284:      * This keeps buying flow safe.
285:      */
286:     if (
287:         (function_exists('is_cart') && is_cart()) ||
288:         (function_exists('is_checkout') && is_checkout()) ||
289:         (function_exists('is_account_page') && is_account_page())
290:     ) {
291:         return;
