293: 
294:     $request_path = parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH);
295:     $request_path = trailingslashit($request_path);
296: 
297:     $mobile_shop_path = trailingslashit(parse_url(home_url('/mobile-shop/'), PHP_URL_PATH));
298: 
299:     /*
300:      * Prevent redirect loop.
301:      */
302:     if ($request_path === $mobile_shop_path) {
303:         return;
304:     }
305: 
306:     $is_homepage = is_front_page() || $request_path === '/';
307:     $is_shop_page = function_exists('is_shop') && is_shop();
308: 
309:     if ($is_homepage || $is_shop_page || $request_path === '/shop/') {
310:         wp_safe_redirect(home_url('/mobile-shop/'), 302);
311:         exit;
312:     }
313: }
