 13: 
 14:   var MOBILE_QUERY = '(max-width: 767px)';
 15:   var AUTOSCROLL_MS = 2600;
 16:   var TRANSITION_MS = 520;
 17: 
 18:   var mq = window.matchMedia ? window.matchMedia(MOBILE_QUERY) : null;
 19:   var plateTimers = new WeakMap();
