 21:   var PLATE_SELECTOR = [
 22:     '.collections-stack .collection-box',
 23:     '.collection-link .collection-box',
 24:     '.dkg-collection-plate',
 25:     '.dkg-home-collection-plate'
 26:   ].join(',');
