 28:   var PRODUCT_SELECTOR = [
 29:     'li.product',
 30:     '.product-card',
 31:     '.collection-product',
 32:     '.dkg-product-card',
 33:     '.wc-block-grid__product',
 34:     'a[href*="/product/"]'
 35:   ].join(',');
 36: 
 37:   var TRACK_SELECTOR = [
 38:     'ul.products',
 39:     '.products',
 40:     '.product-row',
 41:     '.collection-products',
 42:     '.wc-block-grid__products'
 43:   ].join(',');
 44: 
 45:   function isOldMobileShopPage() {
 46:     return document.body.classList.contains('page-mobile-shop') ||
 47:       document.body.classList.contains('page-template-page-mobile-shop');
 48:   }
 49: 
 50:   function isProbablyHomepage() {
 51:     return document.body.classList.contains('home') ||
 52:       document.body.classList.contains('front-page') ||
 53:       document.body.classList.contains('page-template-front-page') ||
 54:       !!document.querySelector('.collections-stack');
 55:   }
 56: 
 57:   function isMobile() {
 58:     return !mq || mq.matches;
 59:   }
 60: 
 61:   function uniqueElements(list) {
 62:     var seen = [];
 63:     var out = [];
 64: 
 65:     Array.prototype.forEach.call(list, function (el) {
 66:       if (!el || seen.indexOf(el) !== -1) {
 67:         return;
 68:       }
 69: 
 70:       seen.push(el);
 71:       out.push(el);
 72:     });
 73: 
 74:     return out;
 75:   }
 76: 
 77:   function hasProductClass(el) {
 78:     return !!(
 79:       el &&
 80:       el.matches &&
 81:       el.matches('li.product, .product-card, .collection-product, .dkg-product-card, .wc-block-grid__product')
 82:     );
 83:   }
 84: 
 85:   function closestProductElement(node, plate) {
 86:     var current;
 87: 
 88:     if (!node || !plate) {
 89:       return null;
 90:     }
 91: 
 92:     current = node;
 93: 
 94:     while (current && current !== plate && current.nodeType === 1) {
 95:       if (hasProductClass(current)) {
 96:         return current;
 97:       }
 98: 
 99:       current = current.parentElement;
100:     }
101: 
102:     if (
103:       node.matches &&
104:       node.matches('a[href*="/product/"]') &&
105:       plate.contains(node)
106:     ) {
107:       return node;
108:     }
109: 
110:     return null;
111:   }
112: 
113:   function stopPlateTimer(plate) {
114:     var timer = plateTimers.get(plate);
115: 
116:     if (timer) {
117:       window.clearInterval(timer);
118:       plateTimers.delete(plate);
119:     }
120:   }
121: 
122:   function removeMobileCarousel(plate) {
123:     var viewports = plate.querySelectorAll(':scope > .dkg-mobile-carousel-viewport');
124: 
125:     Array.prototype.forEach.call(viewports, function (viewport) {
126:       viewport.remove();
127:     });
128:   }
129: 
130:   function clearPlate(plate) {
131:     var marked;
132: 
133:     stopPlateTimer(plate);
134:     removeMobileCarousel(plate);
135: 
136:     plate.classList.remove('dkg-mobile-main-plate-prepared');
137:     plate.classList.remove('dkg-mobile-main-scrolls-after-3');
138:     plate.classList.remove('dkg-mobile-main-no-scroll');
139:     plate.classList.remove('dkg-mobile-main-count-1');
140:     plate.classList.remove('dkg-mobile-main-count-2');
141:     plate.classList.remove('dkg-mobile-main-count-3');
142: 
143:     marked = plate.querySelectorAll(
144:       '.dkg-mobile-original-product-source, .dkg-mobile-original-track-source, .dkg-mobile-main-visible-product, .dkg-mobile-main-extra-product'
145:     );
146: 
147:     Array.prototype.forEach.call(marked, function (el) {
148:       el.classList.remove('dkg-mobile-original-product-source');
149:       el.classList.remove('dkg-mobile-original-track-source');
150:       el.classList.remove('dkg-mobile-main-visible-product');
151:       el.classList.remove('dkg-mobile-main-extra-product');
152:       el.removeAttribute('aria-hidden');
153:     });
154:   }
155: 
156:   function findProductsInPlate(plate) {
157:     var raw = plate.querySelectorAll(PRODUCT_SELECTOR);
158:     var mapped = [];
159: 
160:     Array.prototype.forEach.call(raw, function (node) {
161:       var product = closestProductElement(node, plate);
162: 
163:       if (product) {
164:         mapped.push(product);
165:       }
166:     });
167: 
168:     return uniqueElements(mapped).filter(function (product) {
169:       if (!product || !product.classList) {
170:         return false;
171:       }
172: 
173:       if (product.closest('.dkg-mobile-carousel-viewport')) {
174:         return false;
175:       }
176: 
177:       if (product.classList.contains('collection-link')) {
178:         return false;
179:       }
180: 
181:       if (product.classList.contains('collection-label')) {
182:         return false;
183:       }
184: 
185:       if (product.closest('.site-header')) {
186:         return false;
187:       }
188: 
189:       return true;
190:     });
191:   }
192: 
193:   function markOriginalSources(plate, products) {
194:     products.forEach(function (product, index) {
195:       product.classList.add('dkg-mobile-original-product-source');
196: 
197:       if (index < 3) {
198:         product.classList.add('dkg-mobile-main-visible-product');
199:       } else {
200:         product.classList.add('dkg-mobile-main-extra-product');
201:       }
202: 
203:       var track = product.closest(TRACK_SELECTOR);
204:       if (track && track !== plate && !track.classList.contains('collection-bg')) {
205:         track.classList.add('dkg-mobile-original-track-source');
206:       }
207:     });
208:   }
209: 
210:   function createViewportAndTrack(plate, products) {
211:     var viewport = document.createElement('div');
212:     var track = document.createElement('div');
213: 
214:     viewport.className = 'dkg-mobile-carousel-viewport';
215:     track.className = 'dkg-mobile-product-track dkg-mobile-track-no-animate';
216: 
217:     products.forEach(function (product) {
218:       var clone = product.cloneNode(true);
219: 
220:       clone.classList.remove('dkg-mobile-original-product-source');
221:       clone.classList.remove('dkg-mobile-original-track-source');
222:       clone.classList.add('dkg-mobile-product-item');
223:       clone.setAttribute('data-dkg-mobile-display-clone', '1');
224: 
225:       track.appendChild(clone);
226:     });
227: 
228:     viewport.appendChild(track);
229:     plate.appendChild(viewport);
230: 
231:     return {
232:       viewport: viewport,
233:       track: track,
234:       displayItems: Array.prototype.slice.call(track.children)
235:     };
236:   }
237: 
238:   function makeLoopClones(track, displayItems) {
239:     var clones = [];
240: 
241:     displayItems.slice(0, 3).forEach(function (item) {
242:       var clone = item.cloneNode(true);
243: 
244:       clone.classList.add('dkg-mobile-product-clone');
245:       clone.setAttribute('data-dkg-mobile-loop-clone', '1');
246: 
247:       track.appendChild(clone);
248:       clones.push(clone);
249:     });
250: 
251:     return clones;
252:   }
253: 
254:   function setTrackPosition(track, index, stepPx, animate) {
255:     var x = -(index * stepPx);
256: 
257:     track.classList.toggle('dkg-mobile-track-animate', !!animate);
258:     track.classList.toggle('dkg-mobile-track-no-animate', !animate);
259: 
260:     track.style.setProperty(
261:       'transform',
262:       'translate3d(' + x + 'px, 0, 0)',
263:       'important'
264:     );
265:   }
266: 
267:   function styleProductItems(items, slotWidth) {
268:     items.forEach(function (product) {
269:       product.classList.add('dkg-mobile-product-item');
270: 
271:       product.style.setProperty('flex', '0 0 ' + slotWidth + 'px', 'important');
272:       product.style.setProperty('width', slotWidth + 'px', 'important');
273:       product.style.setProperty('min-width', slotWidth + 'px', 'important');
274:       product.style.setProperty('max-width', slotWidth + 'px', 'important');
275:       product.style.setProperty('height', '100%', 'important');
276:       product.style.setProperty('max-height', '100%', 'important');
277: 
278:       product.removeAttribute('aria-hidden');
279:     });
280:   }
281: 
282:   function startAutoScroll(plate, track, originalCount, stepPx) {
283:     var index = 0;
284:     var timer;
285: 
286:     stopPlateTimer(plate);
287: 
288:     if (originalCount <= 3) {
289:       setTrackPosition(track, 0, stepPx, false);
290:       return;
291:     }
292: 
293:     setTrackPosition(track, 0, stepPx, false);
294: 
295:     timer = window.setInterval(function () {
296:       index += 1;
297:       setTrackPosition(track, index, stepPx, true);
298: 
299:       if (index >= originalCount) {
300:         window.setTimeout(function () {
301:           index = 0;
302:           setTrackPosition(track, 0, stepPx, false);
303:         }, TRANSITION_MS + 40);
304:       }
305:     }, AUTOSCROLL_MS);
306: 
307:     plateTimers.set(plate, timer);
308:   }
309: 
310:   function preparePlate(plate) {
311:     var products = findProductsInPlate(plate);
312:     var setup;
313:     var viewport;
314:     var track;
315:     var displayItems;
316:     var loopClones = [];
317:     var allDisplayItems;
318:     var viewportWidth;
319:     var gap;
320:     var slotWidth;
321:     var stepPx;
322: 
323:     if (!products.length) {
324:       return;
325:     }
326: 
327:     plate.classList.add('dkg-mobile-main-plate-prepared');
328: 
329:     if (products.length === 1) {
330:       plate.classList.add('dkg-mobile-main-count-1');
331:     } else if (products.length === 2) {
332:       plate.classList.add('dkg-mobile-main-count-2');
333:     } else if (products.length === 3) {
334:       plate.classList.add('dkg-mobile-main-count-3');
335:     } else {
336:       plate.classList.add('dkg-mobile-main-scrolls-after-3');
337:     }
338: 
339:     markOriginalSources(plate, products);
340: 
341:     setup = createViewportAndTrack(plate, products);
342:     viewport = setup.viewport;
343:     track = setup.track;
344:     displayItems = setup.displayItems;
345: 
346:     gap = window.innerWidth <= 390 ? 6 : 8;
347: 
348:     viewport.getBoundingClientRect();
349:     viewportWidth = viewport.getBoundingClientRect().width;
350: 
351:     if (products.length < 3) {
352:       slotWidth = Math.min(
353:         170,
354:         Math.max(96, (viewportWidth - gap) / 2)
355:       );
356:     } else {
357:       slotWidth = (viewportWidth - (gap * 2)) / 3;
358:     }
359: 
360:     if (!Number.isFinite(slotWidth) || slotWidth < 40) {
361:       slotWidth = 100;
362:     }
363: 
364:     stepPx = slotWidth + gap;
365: 
366:     if (products.length > 3) {
367:       loopClones = makeLoopClones(track, displayItems);
368:     }
369: 
370:     allDisplayItems = displayItems.concat(loopClones);
371: 
372:     plate.style.setProperty('--dkg-mobile-gap-px', gap + 'px');
373:     plate.style.setProperty('--dkg-mobile-slot-px', slotWidth + 'px');
374:     plate.style.setProperty('--dkg-mobile-step-px', stepPx + 'px');
375: 
376:     styleProductItems(allDisplayItems, slotWidth);
377:     setTrackPosition(track, 0, stepPx, false);
378: 
379:     plate.setAttribute('data-dkg-mobile-products', String(products.length));
380:     plate.setAttribute('data-dkg-mobile-slot-width', String(slotWidth));
381:     plate.setAttribute('data-dkg-mobile-step-width', String(stepPx));
382:     plate.setAttribute('data-dkg-mobile-viewport-width', String(viewportWidth));
383:     plate.setAttribute('data-dkg-mobile-autoscroll', products.length > 3 ? 'yes' : 'no');
384: 
385:     startAutoScroll(plate, track, products.length, stepPx);
386:   }
